import{_ as t,o as a,c as o,l as n,t as i,N as r}from"./chunks/framework.Bbd9fWQx.js";const g=JSON.parse('{"title":"gitformat-bundle | x-cmd man (git man5) | The bundle file format","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitformat-bundle - The bundle file format","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitformat-bundle | x-cmd man (git man5) | The bundle file format"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitformat-bundle - The bundle file format"}]]},"headers":[],"params":{"isMan":true,"man":"gitformat-bundle","category":"git man5","desc":"The bundle file format"},"relativePath":"git/man5/gitformat-bundle.md","filePath":"git/man5/gitformat-bundle.md"}'),s={name:"git/man5/gitformat-bundle.md"},l={class:"visually-hidden"},d=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitformat-bundle - The bundle file format</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.bundle</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.bdl</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The Git bundle format is a format that represents both refs and Git objects. A bundle is a header in a format similar to <strong>git-show-ref</strong>(1) followed by a pack in *.pack format.</p><p>The format is created and read by the <strong>git-bundle</strong>(1) command, and supported by e.g. <strong>git-fetch</strong>(1) and <strong>git-clone</strong>(1).</p><h2 id="format" tabindex="-1">FORMAT <a class="header-anchor" href="#format" aria-label="Permalink to &quot;FORMAT&quot;">​</a></h2><p>We will use ABNF notation to define the Git bundle format. See <strong>gitprotocol-common</strong>(5) for the details.</p><p>A v2 bundle looks like this:</p><blockquote><pre><code>bundle    = signature *prerequisite *reference LF pack
signature = &quot;# v2 git bundle&quot; LF

prerequisite = &quot;-&quot; obj-id SP comment LF
comment      = *CHAR
reference    = obj-id SP refname LF

pack         = ... ; packfile
</code></pre></blockquote><p>A v3 bundle looks like this:</p><blockquote><pre><code>bundle    = signature *capability *prerequisite *reference LF pack
signature = &quot;# v3 git bundle&quot; LF

capability   = &quot;@&quot; key [&quot;=&quot; value] LF
prerequisite = &quot;-&quot; obj-id SP comment LF
comment      = *CHAR
reference    = obj-id SP refname LF
key          = 1*(ALPHA / DIGIT / &quot;-&quot;)
value        = *(%01-09 / %0b-FF)

pack         = ... ; packfile
</code></pre></blockquote><h2 id="semantics" tabindex="-1">SEMANTICS <a class="header-anchor" href="#semantics" aria-label="Permalink to &quot;SEMANTICS&quot;">​</a></h2><p>A Git bundle consists of several parts.</p><blockquote><p>·</p><p>&quot;Capabilities&quot;, which are only in the v3 format, indicate functionality that the bundle requires to be read properly.</p></blockquote><blockquote><p>·</p><p>&quot;Prerequisites&quot; lists the objects that are NOT included in the bundle and the reader of the bundle MUST already have, in order to use the data in the bundle. The objects stored in the bundle may refer to prerequisite objects and anything reachable from them (e.g. a tree object in the bundle can reference a blob that is reachable from a prerequisite) and/or expressed as a delta against prerequisite objects.</p></blockquote><blockquote><p>·</p><p>&quot;References&quot; record the tips of the history graph, iow, what the reader of the bundle CAN &quot;git fetch&quot; from it.</p></blockquote><blockquote><p>·</p><p>&quot;Pack&quot; is the pack data stream &quot;git fetch&quot; would send, if you fetch from a repository that has the references recorded in the &quot;References&quot; above into a repository that has references pointing at the objects listed in &quot;Prerequisites&quot; above.</p></blockquote><p>In the bundle format, there can be a comment following a prerequisite obj-id. This is a comment and it has no specific meaning. The writer of the bundle MAY put any string here. The reader of the bundle MUST ignore the comment.</p><h3 id="note-on-the-shallow-clone-and-a-git-bundle" tabindex="-1">Note on the shallow clone and a Git bundle <a class="header-anchor" href="#note-on-the-shallow-clone-and-a-git-bundle" aria-label="Permalink to &quot;Note on the shallow clone and a Git bundle&quot;">​</a></h3><p>Note that the prerequisites does not represent a shallow-clone boundary. The semantics of the prerequisites and the shallow-clone boundaries are different, and the Git bundle v2 format cannot represent a shallow clone repository.</p><h2 id="capabilities" tabindex="-1">CAPABILITIES <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;CAPABILITIES&quot;">​</a></h2><p>Because there is no opportunity for negotiation, unknown capabilities cause <em>git bundle</em> to abort.</p><blockquote><p>·</p><p><strong>object-format</strong> specifies the hash algorithm in use, and can take the same values as the <strong>extensions.objectFormat</strong> configuration value.</p></blockquote><blockquote><p>·</p><p><strong>filter</strong> specifies an object filter as in the <strong>--filter</strong> option in <strong>git-rev-list</strong>(1). The resulting pack-file must be marked as a <strong>.promisor</strong> pack-file after it is unbundled.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,28);function h(e,u,c,p,b,m){return a(),o("div",null,[n("h1",l,i(e.$params.man),1),d])}const q=t(s,[["render",h]]);export{g as __pageData,q as default};
